class AlarmConverter(object):
    def __init__(self, emss_alarm_output):
        if emss_alarm_output == 'EMPTY':
            self.alarm_list = []
        else:
            self.alarm_list = emss_alarm_output
            self._add_hex_value_of_id(self.alarm_list)

    def get_list_of_alarm_ids(self):
        return self._get_list_of_alarm_details_by_key("ID")

    def get_list_of_hex_alarm_ids(self):
        return self._get_list_of_alarm_details_by_key("HEXID")

    def _get_list_of_alarm_details_by_key(self, key):
        return [alarm[key] for alarm in self.alarm_list]

    def _add_hex_value_of_id(self, emss_alarm_output):
        for alarm in emss_alarm_output:
            alarm["HEXID"] = hex(int(alarm['ID'])).lstrip('0x')

    def has_alarm_occured(self, alarm_id, criteria="ID"):
        return bool(str(alarm_id) in self._get_list_of_alarm_details_by_key(criteria))
